    int getLucky(string s, int k) {
        string digits = "";
        for (char c : s) digits += to_string(c - 'a' + 1);
        int val = 0;
        for (char c : digits) val += c - '0';
        for (int i = 1; i < k; i++) {
            int nextVal = 0;
