class Solution {
    public int getLucky(String s, int k) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) sb.append(c - 'a' + 1);
        int val = 0;
        for (char c : sb.toString().toCharArray()) val += c - '0';
        for (int i = 1; i < k; i++) {
            int nextVal = 0;
            while (val > 0) {
                nextVal += val % 10;
                val /= 10;
            }
            val = nextVal;
        }
        return val;
    }
}

var getLucky = function(s, k) {
  let digits = '';
  for (const c of s) digits += String(c.charCodeAt(0) - 96);
  let val = 0;
  for (const c of digits) val += Number(c);
  for (let i = 1; i < k; i++) {
    let nextVal = 0;
    while (val > 0) {
      nextVal += val % 10;
      val = Math.floor(val / 10);
    }
    val = nextVal;
  }
  return val;
};
